fn combiner_recv_inductive(pre: Self, post: Self) {
    let j = pre.combiner.get_Collecting_elems().len();
    let pre_elems = pre.combiner.get_Collecting_elems();

    // Prove not_waiting_inv for post:
    // clients and slots are unchanged, so this follows from pre invariant.
    assert forall |i: nat| post.valid_idx(i) && post.clients.index(i).is_Idle()
        implies !post.slots.index(i) by {
        assert(pre.not_waiting_inv());
        assert(pre.valid_idx(i));
        assert(pre.clients.index(i).is_Idle());
    };

    // Prove waiting_inv for post:
    assert forall |i: nat| post.client_waiting(i)
        implies post.request_stored(i) || post.response_stored(i) || post.combiner_has(i) by {

        // clients are unchanged, so client_waiting is the same
        assert(pre.client_waiting(i));
        // from pre waiting_inv
        assert(pre.request_stored(i) || pre.response_stored(i) || pre.combiner_has(i)) by {
            assert(pre.waiting_inv());
        };

        if i == j {
            // pre.combiner_has(j) is false: would require j < pre_elems.len() = j
            assert(!pre.combiner_has(j)) by {
                assert(pre.combiner.is_Collecting());
                // j == pre_elems.len(), so j < j is false
            };
            // pre.response_stored(j) is false: slots[j]=true but response_stored => !slots[j]
            assert(pre.slots.index(j) == true);
            assert(!pre.response_stored(j)) by {
                assert(pre.response_stored_inv());
            };
            // so pre.request_stored(j) must hold
            assert(pre.request_stored(j));
            // In post, combiner_has(j) because post_elems[j] = Some(...)
            assert(post.combiner_has(j)) by {
                assert(post.combiner.is_Collecting());
                let post_elems = post.combiner.get_Collecting_elems();
                assert(post_elems.len() == j + 1);
                assert(j < post_elems.len());
                assert(post_elems.index(j as int).is_Some());
            };
        } else {
            // i != j: request[i] and response[i] unchanged; combiner[i] same if i < j
            if pre.request_stored(i) {
                // only j was removed from requests, so i's request still there
                assert(post.request_stored(i));
            } else if pre.response_stored(i) {
                assert(post.response_stored(i));
            } else {
                // pre.combiner_has(i): i < pre_elems.len() and pre_elems[i].is_Some()
                assert(pre.combiner_has(i));
                assert(post.combiner_has(i)) by {
                    assert(post.combiner.is_Collecting());
                    let post_elems = post.combiner.get_Collecting_elems();
                    // post_elems = pre_elems.push(...)
                    // For i < pre_elems.len(), post_elems[i] == pre_elems[i]
                    assert(i < pre_elems.len());
                    assert(pre_elems.index(i as int).is_Some());
                    assert(post_elems.index(i as int) == pre_elems.index(i as int));
                    assert(i < post_elems.len());
                };
            }
        }
    };

    // Prove request_stored_inv for post:
    // post.requests = pre.requests with j removed
    // For any i where post.request_stored(i): i != j and pre.request_stored(i)
    assert forall |i: nat| post.request_stored(i)
        implies post.client_waiting(i)
            && post.requests.index(i).rid == post.clients.index(i).get_Waiting_rid()
            && post.slots.index(i) by {
        // i != j since j was removed
        assert(i != j);
        // pre.request_stored(i) since only j was removed
        assert(pre.request_stored(i));
        assert(pre.request_stored_inv());
        // clients and slots unchanged
        assert(pre.client_waiting(i));
        assert(pre.requests.index(i).rid == pre.clients.index(i).get_Waiting_rid());
        assert(pre.slots.index(i));
    };

    // Prove response_stored_inv for post:
    // responses unchanged
    assert forall |i: nat| post.response_stored(i)
        implies post.client_waiting(i)
            && post.responses.index(i).rid == post.clients.index(i).get_Waiting_rid()
            && !post.slots.index(i) by {
        // pre.response_stored(i) since responses unchanged
        assert(pre.response_stored(i));
        assert(pre.response_stored_inv());
        // clients and slots unchanged
        assert(pre.client_waiting(i));
        assert(pre.responses.index(i).rid == pre.clients.index(i).get_Waiting_rid());
        assert(!pre.slots.index(i));
    };

    // Prove combiner_has_inv for post:
    assert forall |i: nat| post.combiner_has(i)
        implies post.client_waiting(i)
            && post.slots.index(i)
            && post.combiner_rid(i) == post.clients.index(i).get_Waiting_rid()
            && !post.request_stored(i) by {
        assert(post.combiner.is_Collecting());
        let post_elems = post.combiner.get_Collecting_elems();
        if i == j {
            // post_elems[j] = Some(request.rid) where request came from pre.requests[j]
            // We know pre.request_stored(j) and pre.request_stored_inv()
            assert(pre.slots.index(j) == true);
            assert(!pre.response_stored(j)) by {
                assert(pre.response_stored_inv());
            };
            assert(!pre.combiner_has(j)) by {
                assert(pre.combiner.is_Collecting());
            };
            assert(pre.request_stored(j));
            assert(pre.request_stored_inv());
            assert(pre.client_waiting(j));
            // combiner_rid in post for j
            // post.combiner_rid(j) = post_elems[j].get_Some_0() = request.rid
            // pre.requests[j].rid == pre.clients[j].get_Waiting_rid()
            // since clients unchanged: post.clients[j].get_Waiting_rid() = pre.clients[j].get_Waiting_rid()
            // and pre.requests[j].rid = request.rid (the withdrawn request)
            // We need: post.combiner_rid(j) == post.clients.index(j).get_Waiting_rid()
            assert(post.combiner_rid(j) == post.clients.index(j).get_Waiting_rid());
            // request j was withdrawn, so !post.request_stored(j)
            assert(!post.request_stored(j));
        } else {
            // i < j: pre.combiner_has(i) must hold
            assert(i < pre_elems.len());
            assert(pre_elems.index(i as int) == post_elems.index(i as int));
            assert(pre.combiner_has(i));
            assert(pre.combiner_has_inv());
            assert(pre.client_waiting(i));
            assert(pre.slots.index(i));
            assert(pre.combiner_rid(i) == pre.clients.index(i).get_Waiting_rid());
            assert(!pre.request_stored(i));
            // combiner_rid in post == pre (same elems for i < j)
            assert(post.combiner_rid(i) == pre.combiner_rid(i));
            assert(!post.request_stored(i));
        }
    };
}

